// Regenerate guardd/tests/fixtures/policy-vectors.json:
//   node guardd/tests/fixtures/gen-policy-vectors.mjs "$PWD" > guardd/tests/fixtures/policy-vectors.json
// Signs test policies with node:crypto + cli/hook-core.mjs (policyDigest/policyCanonical) and checks them
// with verifyPolicySignature, so the Rust port is pinned to the JS semantics.
import { createPrivateKey, sign, createPublicKey } from "node:crypto";
import { readFileSync } from "node:fs";
const core = await import(process.argv[2] + "/cli/hook-core.mjs");
const g = JSON.parse(readFileSync(process.argv[2] + "/test/fixtures/guardd/golden.json", "utf8"));
const seed = Buffer.from(g.keys.consoleSeedHex, "hex");
const pkcs8 = Buffer.concat([Buffer.from("302e020100300506032b657004220420", "hex"), seed]);
const priv = createPrivateKey({ key: pkcs8, format: "der", type: "pkcs8" });
const pubB64 = g.keys.consolePublicKeySpkiB64;
function signed(body, tenant, iat) {
  const p = { ...body };
  const digest = core.policyDigest(p);
  const msg = core.policyCanonical({ v: 1, tenant, iat, digest });
  p.policySig = { v: 1, alg: "ed25519", tenant, iat, sig: sign(null, Buffer.from(msg), priv).toString("base64") };
  return p;
}
const body = { threatPolicy: { "21": "block", "7": "quarantine" }, thresholds: { score: 0.85, tiny: 1.5e-7, big: 1e21, neg: -0.0, n: 12345678901234567890 }, list: [1, 2.50, "x y", "\u{1f600}", ""], policyMaxAgeMinutes: 30, revokedKeys: [] };
const text = JSON.stringify(signed(body, "acme", "2026-10-12T09:00:00.000Z"));
const keys = core.parseTrustedKeys(pubB64);
const v = core.verifyPolicySignature(JSON.parse(text), { keys, tenant: "acme" });
const other = JSON.stringify(signed({ a: 1 }, "other", "2026-10-12T09:00:00.000Z"));
const vo = core.verifyPolicySignature(JSON.parse(other), { keys, tenant: "acme" });
console.log(JSON.stringify({ comment: "generated by node:crypto + cli/hook-core.mjs policyDigest/policyCanonical/verifyPolicySignature", publicKey: pubB64, tenant: "acme", policyText: text, jsStatus: v.status, digest: core.policyDigest(JSON.parse(text)), otherTenantText: other, otherTenantJsStatus: vo.status }, null, 1));
